########## anchors.mjs
// Anchor math, published for other packs: how long a frequency's period is, and which
// instant a task's window last opened at or opens next. A renderer of queue state needs
// the same arithmetic the scheduler decides with.
export {
  ACCEPTED_FREQUENCIES, DUE_TERM, ELAPSED_TERM, cadenceOf, cadenceTermFor, holdsOnFailure,
  holdsOnAnyPark, statesConditions,
} from '../src/contract/calendar.mjs';
export {
  periodMs, taskPeriodMs, mostRecentAnchor, nextAnchor,
} from '../src/items/anchors.mjs';
########## delivery.mjs
// The delivery lane, published for other packs: how a task's output becomes a landed
// pull request or a regenerated file, honoring the repo's delivery settings.
export {
  deliveryFor, landDelivery, openDeliveredPull, disposeOpenPull, pullCreateError,
} from '../src/deliver/land-pr.mjs';
export {
  deliverGenerated, baseTip, readAt, remoteUrl,
} from '../src/deliver/deliver-generated.mjs';
export {
  withTaskTrailer,
} from '../src/contract/task-trailer.mjs';
########## dormancy.mjs
// Whether a member's scheduler is dormant, published for the packs that must ask it
// from outside: the dashboard (which hides work it knows cannot move) and the fleet
// sweeps (which must not report a stopped scheduler as unhealthy). Re-exported rather
// than reimplemented so a consumer and the queue can never disagree about what the
// declaration means.
export { isDormant, dormancyErrors, TASKS_PACK_ID } from '../src/contract/dormancy.mjs';
########## github.mjs
// The GitHub client a task's worker lands its output with, the Actions environment it
// reads its repo and run from, and the tracker issue it records progress on —
// published for other packs so a worker reaches GitHub the same way the executor does.
//
// The client and two operations, not the port: a worker that needs a further REST
// call asks for the operation to be published rather than composing a path, which is
// what keeps every path this pack calls countable in `src/world/github.mjs`.
export {
  makeGh, dispatchWorkflow,
} from '../src/world/github.mjs';
export {
  SCHEDULER_WORKFLOW_FILE, EXECUTOR_WORKFLOW_FILE,
} from '../src/world/actions.mjs';
export {
  findOrCreateTracker, writeTracker,
} from '../src/items/tracker.mjs';
########## merge-policy.mjs
// The auto-merge policy engine, published for other packs: the verdict an `automerge`
// declaration compiles to, and the merge-rules.json compiler, so a pack's own tests can
// assert its policies and declared rules against the same evaluator the landing lane and
// the automerge-policy-scope gate apply.
export {
  policyVerdict, policyExpression, declaredMergeRules, AUTOMERGE_TRAILER,
} from '../src/contract/merge-policy.mjs';
export {
  diffEntries,
} from '../src/session/merge-policy-run.mjs';
########## preconditions.mjs
// The precondition engine, published for other packs: the signal union a declaration's
// conditions resolve to, the task-local term file, and the one seam that turns a
// discovered task plus its collected signals into a verdict — the same call the
// executor makes at pick.
export {
  preconditionSignals,
} from '../src/contract/precondition-policy.mjs';
export {
  loadTaskTerms, TASK_TERMS_FILE,
} from '../src/contract/task-terms.mjs';
export {
  evaluatePrecondition,
} from '../src/contract/precondition.mjs';
########## pull-requests.mjs
// The merged-PR field derivations, published for other packs: how a pull request names
// the issue it closes, and how a span between two timestamps becomes hours.
//
// Published because the usage fold files a merged PR's lead times under the issue its
// body closes, and a page drawing the same series for the days the fold has not
// reached yet has to find that issue by the same rule — otherwise the two halves of
// one series disagree about which PRs have a lead time at all.
//
// Re-exported from the pure module rather than from the reader beside it: the consumer
// is a page that runs in a browser, where the reader's `process.env` and its listing
// would not load.
export { closesIssueIn, hoursBetween } from '../src/items/pr-fields.mjs';
########## signals.mjs
// The signal shapes a task's precondition is handed, published for other packs: the
// collector's own definitions, so a pack asserting what its task will see asserts
// against what the executor actually produces.
export * from '../src/signals/index.mjs';
export { localSignalContext } from '../src/world/git.mjs';
########## substantive-commit.mjs
// Whether a default-branch commit is genuine project work, published for the packs
// that must ask it from outside — the dashboard, which marks a member sleepy when
// nothing meaningful landed in its window, and must decide that by the same test the
// member's own preconditions used.
export { isSubstantiveCommit, HOUSEKEEPING } from '../src/signals/substantive-commit.mjs';
########## task-contract.mjs
// Task-declaration validation, published for other packs: the contract a
// `tasks/<name>/task.json` is held to, so a pack's own tests can exercise its task
// declarations against the same rules the scheduler applies — and the evaluator that
// runs a declaration's precondition the way the executor does.
export {
  validateTaskDeclaration, normalizeTaskDeclaration, canonicalOutcome, opensPullRequest,
  isScheduledTask, DEFAULT_AGENT_MODEL,
} from '../src/contract/task-contract.mjs';
export {
  evaluatePrecondition,
} from '../src/contract/precondition.mjs';
########## task-declaration.mjs
// The task declaration as text, published for other packs: the reader that lifts fields
// out of a declaration, and the agentic defaults the loader fills — without a Node
// built-in, so a browser bundle can load it.
export {
  parseTaskDeclaration,
} from '../src/contract/task-declaration-text.mjs';
export {
  applyTaskDefaults,
} from '../src/contract/task-defaults.mjs';
########## usage-format.mjs
// The usage aggregate's codec, published for other packs: the row fields, the file
// version, and the encode/decode pair. A fleet-wide aggregator copies members' rows
// through, so it reads them back with the same codec the member wrote them with.
export * from '../src/items/usage-format.mjs';
export { USAGE_PATH } from '../tasks/usage-fold/worker.mjs';

########## verification.mjs
// The production-verification spec as a FORMAT, published for the packs that write
// one. A verification item's body is composed by one pack's skill and read by this
// pack's probe worker, so the two could drift with nothing red: the writer's own
// tests assert the body it tells an agent to write against the parser that will
// actually read it, and that needs an address other packs may import.
//
// Three names, not the worker: what a spec looks like, and the re-arm cadence a
// not-yet-live run reschedules itself on.
export { parseVerificationSpec, parseRetryEvery, RETRY_FIELD } from '../tasks/verify-production/probes.mjs';
########## wake.mjs
// Which of a repo's declared tasks a scheduler run would instantiate an item for at a
// given instant — the plan a forced sweep has to predict. Its own module rather than a
// line in work-items.mjs: the scheduler run reaches Node built-ins, and the dashboard
// loads work-items.mjs unbundled in a browser, where only relative specifiers resolve.
export { planWake } from '../src/schedule/run.mjs';
########## work-items.mjs
// The work-item vocabulary, published for other packs: the title grammar that IS a
// work item's identity, the outcome/status decode over its labels (every legacy
// spelling included), lease state, and the pick order over the open queue.
// Re-exported rather than reimplemented so a consumer and the queue can never disagree
// about what a title means.
//
// NAMED, not `export *`: what this file lists IS the promise, so a reader sees the
// whole of it here and an internal rename cannot quietly widen or narrow it. The
// queue's own GitHub listings are deliberately absent — reading the queue is this
// pack's work, and a consumer wanting queue state renders what it was given.
export {
  WORK_PREFIX, ORIGIN_AD_HOC, ASKED_FOR_ORIGINS, QUEUE_LABELS, READY, URGENT, BLOCKED,
  EXECUTING, AGENT, NEEDS_HUMAN, TASK_DONE, STATUS_READY, STATUS_BLOCKED,
  STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT, STATUS_NEEDS_HUMAN_APPROVAL,
  STATUS_NEEDS_HUMAN_FAILURE, NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL,
  NEEDS_HUMAN_DECISION, NEEDS_HUMAN_FAILURE, PARK_KINDS, PARK_PREFIX, PARK_STATUSES,
  OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE, CLAIM_MARKER, HANDOFF_MARKER,
  EPISODE_MARKER, MACHINE_BLOCK_START, MACHINE_BLOCK_END, parseWorkItemTitle,
  parseWorkItemBody, parseRequestFields, parseLastVerdict, machineBlockOf,
  withMachineBlock, taskIdFromPath, labelNames, hasLabel, statusOf, statusesOn,
  spellingsOf, outcomeOf, isQueueItem, isParked, isBlockingPark, parkKindOf,
  triageLabelFor,
} from '../src/items/work-item.mjs';
export {
  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STALE_READY_PERIODS, STUCK_BLOCKED_MS,
} from '../src/items/leases.mjs';
export {
  pickOrder,
} from '../src/items/pick-order.mjs';
export {
  NEEDS_HUMAN_LABEL,
} from '../src/session/dispatch.mjs';

