import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readdirSync, readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

// THE SURFACE IS A PROMISE, SO IT IS WORTH ONE TEST THAT THE PROMISE STILL LINKS.
// Every module here re-exports named symbols out of `src/`, which is exactly what lets
// the internals be reorganised without touching a consumer — and exactly what breaks
// silently when an internal rename lands and no canon file happened to import the old
// name. `export { X } from '...'` fails at LINK time when X is gone, so importing each
// module IS the assertion: nothing here needs to be called.
//
// Nothing in this repo imported the surface before (the canon reads it, but only the
// modules it happens to need), so a member could be the first to discover a dead
// re-export — in its own repo, at run time, which is the whole failure this suite exists
// to move earlier.

const HERE = dirname(fileURLToPath(import.meta.url));
const SURFACE = join(HERE, '..', 'shared-code');

const modules = readdirSync(SURFACE).filter((f) => f.endsWith('.mjs')).sort();

test('the published surface is non-empty', () => {
  assert.ok(modules.length > 5, `expected a real surface, found ${modules.length} modules`);
});

for (const file of modules) {
  test(`shared-code/${file} links and publishes something`, async () => {
    const mod = await import(join(SURFACE, file));
    const names = Object.keys(mod);
    assert.ok(names.length > 0, `${file} publishes nothing — a surface module with no exports is dead weight`);
  });
}

// The README's table is how a consumer FINDS the name it needs; a module absent from it
// is published in name only. Guarded rather than commented, because the two drift in the
// direction that is invisible: adding a module is the moment the row is easiest to skip.
test('every surface module has a row in the README table', () => {
  const readme = readFileSync(join(HERE, '..', 'README.md'), 'utf8');
  const undocumented = modules.filter((f) => !readme.includes(`| \`${f}\` |`));
  assert.deepEqual(undocumented, [],
    `published but not in the README's surface table, so no consumer can find them:\n  ${undocumented.join('\n  ')}`);
});

